"""SP_CH04 — Chapter 4 figures and number checks (continuous random variables)."""
import numpy as np, matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
from matplotlib.patches import FancyBboxPatch, FancyArrowPatch
from scipy.stats import norm, expon, gamma, uniform, lognorm, weibull_min, triang, binom
NAVY, GOLD, EMER, BURG, BLUE, CORAL, IVORY, SLATE = "#0B2545","#C9A227","#1B7F5C","#7A1E2B","#2E86AB","#E07A5F","#FBF8F1","#5B6B7C"
plt.rcParams.update({"font.size":14,"axes.titlesize":15,"axes.labelsize":14,"font.family":"DejaVu Sans","axes.edgecolor":SLATE,"axes.spines.top":False,"axes.spines.right":False,"axes.titlepad":10})
OUT="/home/claude/ch04/fig/"
def save(fig,name): fig.savefig(OUT+name,dpi=300,bbox_inches="tight",facecolor="white",pad_inches=0.15); plt.close(fig)
def rbox(ax,x,y,w,h,fc,ec,lw=2.5): ax.add_patch(FancyBboxPatch((x,y),w,h,boxstyle="round,pad=0,rounding_size=0.12",fc=fc,ec=ec,lw=lw,zorder=2))
sep=lambda fig,xs: [fig.add_artist(plt.Line2D([x,x],[0.05,0.95],color=SLATE,lw=1.2,ls=":")) for x in xs]
rng=np.random.default_rng(4); wait=rng.exponential(1/3,20000)   # minutes to next call, rate 3/min
# Fig 4.1 from histogram to density
fig,axs=plt.subplots(1,3,figsize=(15,4.4),gridspec_kw={"wspace":0.3})
for ax,bins,t in zip(axs,[6,24,96],["(a) 6 bins of 0.5 min","(b) 24 bins of 0.125 min","(c) 96 bins → a smooth curve"]):
    ax.hist(wait,bins=np.linspace(0,3,bins+1),density=True,color=NAVY,alpha=0.85,edgecolor="white")
    if bins==96: x=np.linspace(0,3,300); ax.plot(x,3*np.exp(-3*x),color=GOLD,lw=3,label="density f(t) = 3e^(−3t)"); ax.legend(frameon=False)
    ax.set_xlim(0,3); ax.set_ylim(0,3.2); ax.set_xlabel("t = minutes until the next call"); ax.set_ylabel("probability per minute"); ax.set_title(t,color=NAVY)
sep(fig,[0.365,0.66]); save(fig,"SP_Fig_CH04_01.png")
# Fig 4.2 density area & cdf
x=np.linspace(0,3,400); f=3*np.exp(-3*x); F=1-np.exp(-3*x)
fig,axs=plt.subplots(1,2,figsize=(13,4.6),gridspec_kw={"wspace":0.3})
ax=axs[0]; ax.plot(x,f,color=NAVY,lw=2.5); m=(x>=0.5)&(x<=1.0); ax.fill_between(x[m],f[m],color=GOLD,alpha=0.7)
ax.text(0.75,0.9,"P(0.5 < T < 1)\n= area = 0.173",ha="center",color=NAVY,fontsize=12,fontweight="bold"); ax.set_xlabel("t (minutes)"); ax.set_ylabel("density f(t)"); ax.set_title("(a) Probability = area under the density",color=NAVY); ax.set_ylim(0,3.2)
ax=axs[1]; ax.plot(x,F,color=GOLD,lw=2.5); ax.plot([0.5,0.5],[0,F[np.searchsorted(x,0.5)]],color=SLATE,ls=":"); ax.plot([1,1],[0,F[np.searchsorted(x,1)]],color=SLATE,ls=":")
ax.plot([0,0.5],[1-np.exp(-1.5)]*2,color=SLATE,ls=":"); ax.plot([0,1],[1-np.exp(-3)]*2,color=SLATE,ls=":")
ax.text(1.4,0.55,"F(1) − F(0.5)\n= 0.950 − 0.777 = 0.173",color=NAVY,fontsize=12,fontweight="bold"); ax.set_xlabel("t (minutes)"); ax.set_ylabel("F(t) = P(T ≤ t)"); ax.set_title("(b) The cdf is a smooth ramp; no jumps",color=NAVY); ax.set_ylim(0,1.05)
sep(fig,[0.5]); save(fig,"SP_Fig_CH04_02.png")
# Fig 4.3 uniform
fig,axs=plt.subplots(1,2,figsize=(13,4.2),gridspec_kw={"wspace":0.3})
ax=axs[0]; ax.plot([0,8,8,20,20,30],[0,0,1/12,1/12,0,0],color=NAVY,lw=2.5); xx=np.linspace(10,15,50); ax.fill_between(xx,1/12,color=GOLD,alpha=0.7); ax.text(12.5,0.095,"P(10 < X < 15) = 5 × (1/12) = 0.417",ha="center",color=NAVY,fontsize=12,fontweight="bold")
ax.set_xlabel("arrival minute within the 8:08–8:20 window"); ax.set_ylabel("density"); ax.set_ylim(0,0.115); ax.set_title("(a) Uniform density on [8, 20]",color=NAVY)
ax=axs[1]; ax.plot([0,8,20,30],[0,0,1,1],color=GOLD,lw=2.5); ax.set_xlabel("x"); ax.set_ylabel("F(x)"); ax.set_ylim(0,1.05); ax.set_title("(b) Its cdf: a straight ramp",color=NAVY)
sep(fig,[0.5]); save(fig,"SP_Fig_CH04_03.png")
# Fig 4.4 exponential + memoryless
fig,axs=plt.subplots(1,2,figsize=(13,4.6),gridspec_kw={"wspace":0.3})
ax=axs[0]; x=np.linspace(0,4,300)
for lam,c in [(0.5,EMER),(1,NAVY),(3,BURG)]: ax.plot(x,lam*np.exp(-lam*x),color=c,lw=2.5,label=f"λ = {lam}  (mean {1/lam:.2f})")
ax.set_xlabel("t"); ax.set_ylabel("density"); ax.set_ylim(0,3.1); ax.legend(frameon=False); ax.set_title("(a) Exponential densities",color=NAVY)
ax=axs[1]; x=np.linspace(0,5,300); lam=1; ax.plot(x,np.exp(-lam*x),color=NAVY,lw=2.5)
ax.fill_between(x[x>=2],np.exp(-x[x>=2]),color=GOLD,alpha=0.6); ax.fill_between(x[x>=3],np.exp(-x[x>=3]),color=BURG,alpha=0.6)
ax.text(2.1,0.5,"P(T > 2) = e⁻²",color=NAVY,fontsize=12); ax.text(3.1,0.25,"P(T > 3) = e⁻³",color=BURG,fontsize=12)
ax.text(1.2,0.85,"P(T > 3 | T > 2) = e⁻³ / e⁻² = e⁻¹ = P(T > 1)",color=NAVY,fontsize=12.5,fontweight="bold")
ax.set_xlabel("t"); ax.set_ylabel("P(T > t) = e^(−λt)"); ax.set_ylim(0,1.05); ax.set_title("(b) Memorylessness (λ = 1)",color=NAVY)
sep(fig,[0.5]); save(fig,"SP_Fig_CH04_04.png")
# Fig 4.5 Erlang
fig,ax=plt.subplots(figsize=(10,4.6)); x=np.linspace(0,4,400)
for k,c in [(1,NAVY),(2,GOLD),(3,EMER),(5,BURG)]: ax.plot(x,gamma.pdf(x,k,scale=1/3),color=c,lw=2.5,label=f"k = {k}: time until the {k}{'st' if k==1 else 'nd' if k==2 else 'rd' if k==3 else 'th'} call (mean {k/3:.2f} min)")
ax.set_xlabel("t (minutes), calls at rate λ = 3 per minute"); ax.set_ylabel("density"); ax.legend(frameon=False); ax.set_ylim(0,3.1)
save(fig,"SP_Fig_CH04_05.png")
# Fig 4.6 normal 68-95-99.7
fig,ax=plt.subplots(figsize=(11,4.8)); x=np.linspace(-4,4,500); y=norm.pdf(x); ax.plot(x,y,color=NAVY,lw=2.5)
for a,c,al in [(1,GOLD,0.75),(2,GOLD,0.45),(3,GOLD,0.25)]: m=(x>=-a)&(x<=a); ax.fill_between(x[m],y[m],color=c,alpha=al)
for a,t,yy in [(1,"68.3%",0.15),(2,"95.4%",0.06),(3,"99.7%",0.015)]: ax.annotate("",xy=(-a,yy),xytext=(a,yy),arrowprops=dict(arrowstyle="<->",color=NAVY,lw=1.6)); ax.text(0,yy+0.012,t,ha="center",color=NAVY,fontsize=12,fontweight="bold")
ax.set_xticks(range(-4,5)); ax.set_xticklabels(["μ−4σ","μ−3σ","μ−2σ","μ−σ","μ","μ+σ","μ+2σ","μ+3σ","μ+4σ"]); ax.set_ylabel("density"); ax.set_ylim(0,0.45)
save(fig,"SP_Fig_CH04_06.png")
# Fig 4.7 demand N(500,80): P(X>600) & 95% level
fig,axs=plt.subplots(1,2,figsize=(13,4.6),gridspec_kw={"wspace":0.3}); x=np.linspace(200,800,500); y=norm.pdf(x,500,80)
ax=axs[0]; ax.plot(x,y,color=NAVY,lw=2.5); m=x>=600; ax.fill_between(x[m],y[m],color=BURG,alpha=0.7); ax.text(640,0.0012,"P(D > 600)\n= P(Z > 1.25)\n= 0.106",color=BURG,fontsize=12,fontweight="bold"); ax.axvline(500,color=SLATE,ls=":"); ax.set_xlabel("daily orders D"); ax.set_ylabel("density"); ax.set_title("(a) Probability of exceeding 600 orders",color=NAVY)
ax=axs[1]; ax.plot(x,y,color=NAVY,lw=2.5); q=norm.ppf(0.95,500,80); m=x<=q; ax.fill_between(x[m],y[m],color=GOLD,alpha=0.6); ax.axvline(q,color=BURG,lw=2); ax.text(q+8,0.0035,f"95th percentile\n= 500 + 1.645×80\n= {q:.0f}",color=BURG,fontsize=12,fontweight="bold"); ax.text(470,0.0015,"95%",color=NAVY,fontsize=14,fontweight="bold",ha="center"); ax.set_xlabel("daily orders D"); ax.set_ylabel("density"); ax.set_title("(b) Capacity for a 95% service level",color=NAVY)
sep(fig,[0.5]); save(fig,"SP_Fig_CH04_07.png")
# Fig 4.8 lognormal / weibull / triangular
fig,axs=plt.subplots(1,3,figsize=(15,4.3),gridspec_kw={"wspace":0.3})
ax=axs[0]; x=np.linspace(0,300,400); ax.plot(x,lognorm.pdf(x,s=0.6,scale=np.exp(np.log(60))),color=NAVY,lw=2.5); ax.axvline(60,color=GOLD,ls="--",lw=2); ax.text(65,0.012,"median 60 €",color=GOLD,fontsize=11); ax.set_xlabel("order value (€)"); ax.set_ylabel("density"); ax.set_title("(a) Lognormal: skewed, never negative",color=NAVY)
ax=axs[1]; x=np.linspace(0,30,400)
for k,c,t in [(0.8,BURG,"k = 0.8: early failures"),(1,NAVY,"k = 1: exponential"),(2.5,EMER,"k = 2.5: wear-out")]: ax.plot(x,weibull_min.pdf(x,k,scale=12),color=c,lw=2.5,label=t)
ax.set_xlabel("lifetime (months)"); ax.set_ylabel("density"); ax.legend(frameon=False,fontsize=10); ax.set_title("(b) Weibull: shape k sets the story",color=NAVY)
ax=axs[2]; ax.plot([0,3,5,10,12],[0,0,2/7,0,0],color=NAVY,lw=2.5); ax.fill_between([3,5,10],[0,2/7,0],color=GOLD,alpha=0.4); ax.set_xlabel("activity duration (days)"); ax.set_ylabel("density"); ax.set_title("(c) Triangular: min 3, mode 5, max 10",color=NAVY); ax.set_ylim(0,0.35)
sep(fig,[0.365,0.66]); save(fig,"SP_Fig_CH04_08.png")
# Fig 4.9 service level: call answered within t
fig,ax=plt.subplots(figsize=(10,4.6)); x=np.linspace(0,8,400); lam=0.5; ax.plot(x,1-np.exp(-lam*x),color=NAVY,lw=2.5)
t90=np.log(10)/lam; ax.axhline(0.9,color=GOLD,ls="--",lw=2); ax.axvline(t90,color=BURG,ls=":",lw=2); ax.text(t90+0.15,0.3,f"t₀.₉₀ = ln(10)/λ = {t90:.2f} min",color=BURG,fontsize=12,fontweight="bold"); ax.text(0.2,0.92,"90% service level",color=GOLD,fontsize=12,fontweight="bold")
ax.set_xlabel("t (minutes of waiting)"); ax.set_ylabel("F(t) = P(wait ≤ t)"); ax.set_ylim(0,1.05); ax.set_xlim(0,8)
save(fig,"SP_Fig_CH04_09.png")
# Fig 4.10 decision figure
fig,ax=plt.subplots(figsize=(17,6.4)); ax.axis("off"); ax.set_xlim(0,17); ax.set_ylim(0,6.4)
def q(x,y,t,w=3.4,h=1.0): rbox(ax,x-w/2,y-h/2,w,h,IVORY,NAVY); ax.text(x,y,t,ha="center",va="center",fontsize=12,color=NAVY,fontweight="bold",zorder=3,linespacing=1.3)
def d(x,y,t,c,w=3.0,h=1.0): rbox(ax,x-w/2,y-h/2,w,h,c,c); ax.text(x,y,t,ha="center",va="center",fontsize=12,color="white",fontweight="bold",zorder=3,linespacing=1.3)
def a(p1,p2): ax.add_patch(FancyArrowPatch(p1,p2,arrowstyle="-|>",color=SLATE,lw=1.8,mutation_scale=14,zorder=1))
q(8.5,5.8,"What is the quantity?",w=4)
q(2.6,4.0,"Waiting time until\na random event",w=4.2); q(7.3,4.0,"Sum of many small\nindependent effects",w=3.8); q(11.2,4.0,"Equally likely\nin an interval",w=3.2); q(15.0,4.0,"Lifetime with\nwear-out / early failures",w=3.6)
for xx in (2.6,7.3,11.2,15.0): a((8.5,5.3),(xx,4.5))
d(1.3,2.1,"Exponential\n(memoryless)",BURG,w=2.4); d(4.0,2.1,"Erlang / Gamma\n(k-th event)",BURG,w=2.7); a((1.9,3.5),(1.3,2.6)); a((3.4,3.5),(4.0,2.6))
d(7.3,2.1,"Normal\nN(μ, σ²)",NAVY); a((7.3,3.5),(7.3,2.6))
d(11.2,2.1,"Uniform\nU(a, b)",EMER); a((11.2,3.5),(11.2,2.6))
d(15.0,2.1,"Weibull\n(k, scale)",BLUE); a((15.0,3.5),(15.0,2.6))
d(5.0,0.6,"Positive & skewed (prices, sizes):  Lognormal",GOLD,w=7.0); d(12.6,0.6,"Expert min / most likely / max:  Triangular or Beta",GOLD,w=7.0)
save(fig,"SP_Fig_CH04_10.png")
# Fig 4.11 simulation of demand
rng=np.random.default_rng(44); D=rng.normal(500,80,20000)
