cbox(6,6.5,"Continuous random variable\nprobability = area under density",NAVY,NAVY,tc="white",w=5.2)
cbox(2.5,4.8,"Density f(x), cdf F(x)\nP(a<X<b) = F(b) − F(a)",w=3.4); cbox(6,4.8,"E[X], Var(X)\n(formulas per family)"); cbox(9.5,4.8,"Percentiles & service\nlevels F⁻¹(q)",w=3.2)
cbox(2.5,3.0,"Uniform\n(Ch 17 seed)",EMER); cbox(6,3.0,"Exponential ⟷ Poisson\nmemoryless (Ch 7, 8)",BURG,w=3.4); cbox(9.5,3.0,"Normal, z-scores\n(CLT in Ch 5)",BLUE)
cbox(2.5,1.1,"Erlang / Gamma\n(k-th event)",GOLD); cbox(6,1.1,"Lognormal, Weibull\n(Ch 12), Triangular",GOLD,w=3.4); cbox(9.5,1.1,"Simulation check\n(Ch 17)",GOLD)
